(7264268, 1129905, 28742, '<td valign="top">This feels like a <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21_F.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21_F.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21_F.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=103142" rel="nofollow" target="_blank">vawendy</a>: Great storytelling, attention to details, terrific processing. Well done whoever you are. :)</td>', 'This feels like a  vawendy: Great storytelling, attention to details, terrific processing. Well done whoever you are. :)', '2014-09-19 03:40:34.000000', NULL, 1),
(7264269, 1130088, 28742, '<td valign="top">This is good to see considering Woody and Gumby have been mortal enemies for 35 years. :P Will be interesting to see if the SC hammers you on the artwork rule for that background. Good luck! :)</td>', 'This is good to see considering Woody and Gumby have been mortal enemies for 35 years. :P Will be interesting to see if the SC hammers you on the artwork rule for that background. Good luck! :)', '2014-09-19 03:42:18.000000', NULL, 1),
