(7264272, 1129912, 28742, '<td valign="top">I LOVE this! Only nitpick is that Woody would be holding a pencil. ;-)</td>', 'I LOVE this! Only nitpick is that Woody would be holding a pencil. ;-)', '2014-09-19 03:49:52.000000', NULL, 1),
(7264273, 1130089, 28742, '<td valign="top">The cat seems genuinely concerned. It''s probably thinking "why is that thing touching me??" ;-)</td>', 'The cat seems genuinely concerned. It''s probably thinking "why is that thing touching me??" ;-)', '2014-09-19 03:51:08.000000', NULL, 1),
