(7264276, 1130108, 28742, '<td valign="top">Uh, yeeeaaahhhhh, I''m sorry, but I''m gonna have to ticket ya.<br/><img alt="'' . substr(''//www.dpchallenged.com/cms/image/DNMC-police.png'', strrpos(''//www.dpchallenged.com/cms/image/DNMC-police.png'', ''/'') + 1) . ''" border="0" src="//www.dpchallenged.com/cms/image/DNMC-police.png"/></td>', 'Uh, yeeeaaahhhhh, I''m sorry, but I''m gonna have to ticket ya.', '2014-09-19 03:54:22.000000', NULL, 1),
