(7264285, 1129800, 28742, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=384221" rel="nofollow" target="_blank">Why do ya think??!</a> ;-) Great job. Love the low-key!</td>', 'Why do ya think??! ;-) Great job. Love the low-key!', '2014-09-19 04:02:27.000000', NULL, 1),
(7264286, 1130027, 28742, '<td valign="top">Clevvvver! And nicely done. :)</td>', 'Clevvvver! And nicely done. :)', '2014-09-19 04:02:53.000000', NULL, 1),
(7264287, 1130068, 28742, '<td valign="top">You realize it''s ok to add texture overlays in advanced now, right? (in case you weren''t informed). ;-) Nice work. I don''t know what "scrumping" is, but whatever you do, don''t eat that apple.</td>', 'You realize it''s ok to add texture overlays in advanced now, right? (in case you weren''t informed). ;-) Nice work. I don''t know what "scrumping" is, but whatever you do, don''t eat that apple.', '2014-09-19 04:06:22.000000', NULL, 1),
(7264288, 1130072, 28742, '<td valign="top">Great job &amp; great lighting!</td>', 'Great job & great lighting!', '2014-09-19 04:06:46.000000', NULL, 1),
