(7265982, 1130095, 86447, '<td valign="top">Just "shrug" it off, Atlas.  :D</td>', 'Just "shrug" it off, Atlas.  :D', '2014-09-24 21:42:51.000000', NULL, 1),
(7265983, 1130046, 86447, '<td valign="top">Well done posing Woody!   I''m not good at that.</td>', 'Well done posing Woody!   I''m not good at that.', '2014-09-24 21:42:55.000000', NULL, 1),
(7265984, 1130068, 86447, '<td valign="top">I''m not a fan of the processing, but the image idea is wonderful</td>', 'I''m not a fan of the processing, but the image idea is wonderful', '2014-09-24 21:43:01.000000', NULL, 1),
(7265985, 1130096, 86447, '<td valign="top">Don''t just stand there and wait!  Go out there and MAKE IT HAPPEN!<br/> <br/> <br/>Lovely image... I really like it.</td>', 'Don''t just stand there and wait!  Go out there and MAKE IT HAPPEN!  Lovely image... I really like it.', '2014-09-24 21:43:30.000000', NULL, 1),
(7265986, 1130049, 86447, '<td valign="top">YaY!    Go, Woody!   I''m so very proud of you!<br/> <br/>...And of your photographer who did a great job of capturing your moment.</td>', 'YaY!    Go, Woody!   I''m so very proud of you! ...And of your photographer who did a great job of capturing your moment.', '2014-09-24 21:43:34.000000', NULL, 1),
(7265987, 1129800, 86447, '<td valign="top">She''ll be back, Woody.   Go clean the kitchen so she''ll be happy when she gets home.<br/> <br/>Lovely, emotive image... love the darkness, yet all of the detail.</td>', 'She''ll be back, Woody.   Go clean the kitchen so she''ll be happy when she gets home. Lovely, emotive image... love the darkness, yet all of the detail.', '2014-09-24 21:43:35.000000', NULL, 1),
(7265988, 1130080, 86447, '<td valign="top">Oh... such an emotive scene!   I''m feeling his misery.</td>', 'Oh... such an emotive scene!   I''m feeling his misery.', '2014-09-24 21:43:37.000000', NULL, 1),
(7265989, 1129949, 86447, '<td valign="top">Way to make the artwork rule work!   <br/> <br/>And dang!  She''s sexy!</td>', 'Way to make the artwork rule work!    And dang!  She''s sexy!', '2014-09-24 21:43:38.000000', NULL, 1),
(7265990, 1130088, 86447, '<td valign="top">I don''t understand the new artwork rule.  I hope you do.  *grin*<br/> <br/>Anyway, I love Gumby and Woody dancing in Paris!    Lovely job of it all!</td>', 'I don''t understand the new artwork rule.  I hope you do.  *grin* Anyway, I love Gumby and Woody dancing in Paris!    Lovely job of it all!', '2014-09-24 21:43:41.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7265991, 1130072, 86447, '<td valign="top">Too cute!   WHERE did you find such a cool album?<br/> <br/>I''m not fond of the background.   The image is so well lit that I don''t think the flowers are necessary and they distract me being so centered between them.<br/> <br/> <br/>I love all of the rest!   Especially how you''ve gotten Woody to be turning the page.</td>', 'Too cute!   WHERE did you find such a cool album? I''m not fond of the background.   The image is so well lit that I don''t think the flowers are necessary and they distract me being so centered between them.  I love all of the rest!   Especially how you''ve gotten Woody to be turning the page.', '2014-09-24 21:43:47.000000', NULL, 1),
(7266151, 1129771, 144271, '<td valign="top">I really like the framing on this</td>', 'I really like the framing on this', '2014-09-25 13:43:50.000000', NULL, 1),
