(7266154, 1129947, 144271, '<td valign="top">Great details</td>', 'Great details', '2014-09-25 13:44:44.000000', NULL, 1),
(7266247, 1130101, 65234, '<td valign="top">Quite the variety, and clearly those plastic people just did NOT understand the job requirements.  Particularly love the "DNMC Police" suit LOL.  Best in show!</td>', 'Quite the variety, and clearly those plastic people just did NOT understand the job requirements.  Particularly love the "DNMC Police" suit LOL.  Best in show!', '2014-09-25 19:04:56.000000', NULL, 1),
(7266248, 1130095, 65234, '<td valign="top">Nicely posed and lit.</td>', 'Nicely posed and lit.', '2014-09-25 19:05:05.000000', NULL, 1),
(7266249, 1129912, 65234, '<td valign="top">He''s pretty good!</td>', 'He''s pretty good!', '2014-09-25 19:05:18.000000', NULL, 1),
(7266250, 1130022, 65234, '<td valign="top">Nicely posed and lit.  That Barbie chick is a different species, you know.  This may not work out long term.</td>', 'Nicely posed and lit.  That Barbie chick is a different species, you know.  This may not work out long term.', '2014-09-25 19:05:51.000000', NULL, 1),
(7266251, 1130027, 65234, '<td valign="top">Bonus point for the punniest title in the contest!  Well played.</td>', 'Bonus point for the punniest title in the contest!  Well played.', '2014-09-25 19:06:14.000000', NULL, 1),
(7266252, 1130042, 65234, '<td valign="top">T hat must be rather disconcerting =:-O</td>', 'T hat must be rather disconcerting =:-O', '2014-09-25 19:06:32.000000', NULL, 1),
