(7266257, 1129685, 65234, '<td valign="top">Aww, poor, lonely Woody.  Why do I feel like the cat is just waiting to attack him?</td>', 'Aww, poor, lonely Woody.  Why do I feel like the cat is just waiting to attack him?', '2014-09-25 19:09:08.000000', NULL, 1),
(7266258, 1129949, 65234, '<td valign="top">The hair is hysterical!  Too bad he''s paying her in non-denominational currency, the cad.</td>', 'The hair is hysterical!  Too bad he''s paying her in non-denominational currency, the cad.', '2014-09-25 19:09:47.000000', NULL, 1),
(7266259, 1130023, 65234, '<td valign="top">Or a doppelganger of sorts.  Excellent setup.</td>', 'Or a doppelganger of sorts.  Excellent setup.', '2014-09-25 19:10:20.000000', NULL, 1),
(7266260, 1129905, 65234, '<td valign="top">He needs eyes to roll.  Cute setup, and even if my interpretation isn''t quite the same as the title it still works.</td>', 'He needs eyes to roll.  Cute setup, and even if my interpretation isn''t quite the same as the title it still works.', '2014-09-25 19:11:20.000000', NULL, 1),
(7266261, 1129947, 65234, '<td valign="top">Hanging out with the wrong sorts of people does not pay, clearly.  Great props.</td>', 'Hanging out with the wrong sorts of people does not pay, clearly.  Great props.', '2014-09-25 19:11:49.000000', NULL, 1),
